select
    count(1) as log_count,
    sum(case when operation_type = 'inbound' then change_quantity else 0 end) as total_inbound,
    sum(case when operation_type = 'outbound' then change_quantity else 0 end) as total_outbound,
    sum(change_quantity) as total_change
from stock_log


        and warehouse_id = #{warehouseId}


        and material_id = #{materialId}


        and operation_type = #{operationType}


        and date(created_at) >= #{startDate}


        and date(created_at) <= #{endDate}

select date(sl.created_at) as log_date, count(1) as log_count, sum(case when sl.operation_type = 'inbound' then sl.change_quantity else 0 end) as inbound_quantity, sum(case when sl.operation_type = 'outbound' then sl.change_quantity else 0 end) as outbound_quantity from stock_log sl
and sl.warehouse_id = #{warehouseId}
and date(sl.created_at) >= #{startDate}
and date(sl.created_at) <= #{endDate}
group by date(sl.created_at) order by log_date desc

select sl.operation_type, CASE sl.operation_type WHEN 'inbound' THEN '入库' WHEN 'outbound' THEN '出库' ELSE '' END as operation_type_name, count(1) as log_count, sum(sl.change_quantity) as total_quantity from stock_log sl
and sl.warehouse_id = #{warehouseId}
and date(sl.created_at) >= #{startDate}
and date(sl.created_at) <= #{endDate}
group by sl.operation_type

